    container: container,
    url: `https://${accountName}.blob.core.windows.net/${container}/${blobName}`,
    status: 'pending',
    note: 'Azure upload requires Azure Storage credentials in n8n'
  };
});

return [{
  json: {
    provider: 'azure',
    container: container,
    results: results,
    total: files.length
  }
}];

